// Templates de mensagem da Meta exigem texto fixo pré-aprovado — a variável {{2}}
// carrega só a frase que muda por status, dentro do template "chamado_ti_atualizacao"
// (ver docs-meta/README.md para o texto exato a cadastrar/aprovar na Meta).
const record = $input.first().json.body.record;
const status = record.status;
const resolucao = record.resolucao;
const titulo = record.titulo;

const explicacoes = {
  em_andamento: 'Nossa equipe de TI já está trabalhando nisso. Em breve você terá uma resposta.',
  aguardando: 'Precisamos de mais informações sobre seu chamado. Entre em contato: wa.me/5511968566862',
  resolvido: `Resolvido!${resolucao ? ` Solução: ${resolucao}` : ''}`,
  fechado: `Chamado encerrado.${resolucao ? ` Solução: ${resolucao}` : ''}`,
};

const statusMensagem = explicacoes[status];
if (!statusMensagem) return [];

return [{ json: { telefone: record.telefone_solicitante, tituloChamado: titulo, statusMensagem } }];
